        }

        // 渲染地图界面
        function renderMapInterface(mapData) {
            if (!mapData) return;

            hasMoveBlock = mapData.moveBlocked;

            // 显示/隐藏移动限制提示
            const movementAlert = document.getElementById('movement-alert');
