        </div>

        <!-- 地点详情区域 -->
        <div id="location-details" class="location-details hidden">
            <div class="detail-header">
                <i class="fas fa-map-marker-alt"></i> <span id="selected-location">未选择</span>
            </div>
            <div class="detail-content">
                <div class="character-section">
                    <div class="section-title"><i class="fas fa-user-friends"></i> 可能遇见的人</div>
                    <div id="location-characters" class="character-list">
                        <!-- 角色列表将在这里动态生成 -->
                    </div>
                </div>
            </div>
            <div class="action-section">
                <button id="confirm-move-btn" class="action-button">
                    <i class="fas fa-walking"></i> 前往此处
                </button>
            </div>
        </div>
    </div>

    <!-- 确认移动弹窗 -->
    <div id="confirm-overlay" class="modal-overlay hidden">
        <div class="confirm-dialog">
            <h4>确认前往</h4>
            <p id="confirm-message"></p>
            <div class="dialog-buttons">
                <button id="cancel-move-btn" class="dialog-button cancel-button">
                    <i class="fas fa-times"></i> 再想想
                </button>
                <button id="execute-move-btn" class="dialog-button confirm-button">
                    <i class="fas fa-check"></i> 出发吧
                </button>
            </div>
        </div>
    </div>

    <script>
        // 全局变量
        let mapData = null;
        let selectedMain = null;
        let selectedSub = null;
        let selectedCharacters = [];
        let hasMoveBlock = false;

        // 解析地图数据
        function parseMapData(text) {
            if (!text || typeof text !== 'string') {
                console.error("无效的地图数据", text);
                return null;
            }

            console.log("开始解析地图数据:", text.substring(0, 50) + "...");

            const data = {
                moveBlocked: false,
                locations: []
            };

            try {
                // 解析移动限制状态
                const moveBlockMatch = /\[MOVEBLOCK:(YES|NO)\]/.exec(text);
                if (moveBlockMatch) {
                    data.moveBlocked = moveBlockMatch[1] === 'YES';
                }

                // 预处理：移除HTML标签以避免干扰
                let cleanText = text.replace(/<[^>]*>/g, '');

                // 将文本分割成多行进行解析
                const lines = cleanText.split('\n');
                let currentMainLocation = null;
                let currentSubLocations = [];

                for (let i = 0; i < lines.length; i++) {
                    const line = lines[i].trim();

                    // 跳过空行和MOVEBLOCK行
                    if (!line || line.startsWith('[MOVEBLOCK:')) continue;

                    // 主地点行 - 以[开头但不是[MOVEBLOCK:
                    if (line.startsWith('[') && !line.startsWith('[MOVEBLOCK:')) {
                        // 如果已经有一个主地点正在处理，保存它
                        if (currentMainLocation) {
                            data.locations.push({
                                name: currentMainLocation,
                                subLocations: currentSubLocations
                            });
                        }

                        // 提取新的主地点名
                        const mainLocationName = line.replace('[', '').trim();
                        console.log("发现主地点:", mainLocationName);
                        currentMainLocation = mainLocationName;
                        currentSubLocations = [];
                    }
                    // 子地点行 - 以-开头
                    else if (line.startsWith('-') && currentMainLocation) {
                        // 格式: - 地点X: 角色1, 角色2
                        const subMatch = /- (.*?):(.*?)$/.exec(line);
                        if (subMatch) {
                            const subName = subMatch[1].trim();
                            const charactersText = subMatch[2].trim();
                            const characters = charactersText.split(',').map(c => c.trim()).filter(c => c);

                            console.log(`  子地点: ${subName}, 角色: ${characters.join(', ') || '无'}`);

                            currentSubLocations.push({
                                name: subName,
                                characters: characters
                            });
                        }
                    }
                    // 主地点结束标记
                    else if (line === ']' && currentMainLocation) {
                        data.locations.push({
                            name: currentMainLocation,
                            subLocations: currentSubLocations
                        });
                        currentMainLocation = null;
                        currentSubLocations = [];
                    }
                }

                // 处理最后一个主地点（如果有且尚未处理）
                if (currentMainLocation) {
                    data.locations.push({
                        name: currentMainLocation,
                        subLocations: currentSubLocations
                    });
                }

                console.log(`解析完成: 找到 ${data.locations.length} 个主地点`);
                if (data.locations.length > 0) {
                    console.log("解析后的地图数据:", data);
                    return data;
                } else {
                    console.error("未找到有效的地点数据");
                    return null;
                }
            } catch (error) {
                console.error("解析地图数据时出错:", error);
                return null;
            }
        }

        // 渲染地图界面
        function renderMapInterface(mapData) {
            if (!mapData) return;

            hasMoveBlock = mapData.moveBlocked;

            // 显示/隐藏移动限制提示
            const movementAlert = document.getElementById('movement-alert');
            if (hasMoveBlock) {
                movementAlert.classList.remove('hidden');
            } else {
                movementAlert.classList.add('hidden');
            }

            // 渲染主地点按钮
            const mainLocationsContainer = document.getElementById('main-locations');
            mainLocationsContainer.innerHTML = '';

            mapData.locations.forEach(location => {
                const button = document.createElement('button');
                button.className = 'location-button';

                // 为不同地点设置不同的图标
                let icon = 'fa-map';
                if (location.name.includes('学校')) icon = 'fa-school';
                else if (location.name.includes('公园')) icon = 'fa-tree';
                else if (location.name.includes('商业')) icon = 'fa-store';
                else if (location.name.includes('住宅')) icon = 'fa-home';
                else if (location.name.includes('站')) icon = 'fa-train';

                button.innerHTML = `<i class="fas ${icon}"></i> ${location.name}`;
                button.dataset.location = location.name;

                button.addEventListener('click', () => selectMainLocation(location));

                if (hasMoveBlock) {
                    button.disabled = true;
                    button.classList.add('disabled');
                }

                mainLocationsContainer.appendChild(button);
            });

            // 隐藏子地点和详情
            document.getElementById('sub-locations').classList.add('hidden');
            document.getElementById('location-details').classList.add('hidden');
        }

        // 选择主地点
        function selectMainLocation(location) {
            if (hasMoveBlock) return;

            selectedMain = location;

            // 高亮选中的主地点按钮
            const allMainButtons = document.querySelectorAll('#main-locations .location-button');
            allMainButtons.forEach(btn => {
                btn.classList.remove('selected');
                if (btn.dataset.location === location.name) {
                    btn.classList.add('selected');
                }
            });

            // 渲染子地点
            const subLocationsContainer = document.getElementById('sub-locations');
            subLocationsContainer.innerHTML = '';

            location.subLocations.forEach(subLocation => {
                const button = document.createElement('button');
                button.className = 'sub-location-button';

                // 为不同子地点设置不同的图标
                let icon = 'fa-map-pin';
                if (subLocation.name.includes('教室')) icon = 'fa-chalkboard';
                else if (subLocation.name.includes('咖啡')) icon = 'fa-coffee';
                else if (subLocation.name.includes('图书')) icon = 'fa-book';
                else if (subLocation.name.includes('商店')) icon = 'fa-shopping-bag';
                else if (subLocation.name.includes('广场')) icon = 'fa-clock';

                button.innerHTML = `<i class="fas ${icon}"></i> ${subLocation.name}`;
                button.dataset.sublocation = subLocation.name;

                button.addEventListener('click', () => selectSubLocation(subLocation));

                subLocationsContainer.appendChild(button);
            });

            // 显示子地点区域
            subLocationsContainer.classList.remove('hidden');

            // 隐藏详情区域
            document.getElementById('location-details').classList.add('hidden');

            // 重置子地点选择
            selectedSub = null;
        }

        // 选择子地点
        function selectSubLocation(subLocation) {
            if (hasMoveBlock) return;

            selectedSub = subLocation;
            selectedCharacters = subLocation.characters;

            // 高亮选中的子地点按钮
            const allSubButtons = document.querySelectorAll('#sub-locations .sub-location-button');
            allSubButtons.forEach(btn => {
                btn.classList.remove('selected');
                if (btn.dataset.sublocation === subLocation.name) {
                    btn.classList.add('selected');
                }
            });

            // 更新地点详情
            document.getElementById('selected-location').textContent = `${selectedMain.name} - ${subLocation.name}`;

            // 更新角色列表
            const charactersContainer = document.getElementById('location-characters');
            charactersContainer.innerHTML = '';

            if (subLocation.characters.length > 0) {
                subLocation.characters.forEach(character => {
                    const charElement = document.createElement('div');
                    charElement.className = 'character-item';
                    charElement.innerHTML = `<i class="fas fa-user"></i> ${character}`;
                    charactersContainer.appendChild(charElement);
                });
            } else {
                const noCharElement = document.createElement('div');
                noCharElement.className = 'character-item empty';
                noCharElement.innerHTML = `<i class="fas fa-user-slash"></i> 这里没有人`;
                charactersContainer.appendChild(noCharElement);
            }

            // 显示详情区域
            document.getElementById('location-details').classList.remove('hidden');
        }

        // 确认移动
        function confirmMove() {
            if (hasMoveBlock || !selectedMain || !selectedSub) return;

            const locationName = `${selectedMain.name} - ${selectedSub.name}`;
            const characters = selectedCharacters.join(', ');

            // 显示确认对话框
            const confirmMessage = document.getElementById('confirm-message');
            if (characters) {
                confirmMessage.textContent = `前往 ${locationName}？你可能会遇见：${characters}`;
            } else {
                confirmMessage.textContent = `前往 ${locationName}？那里好像没有人。`;
            }

            document.getElementById('confirm-overlay').classList.remove('hidden');
        }

        // 执行移动
        function executeMove() {
            if (hasMoveBlock || !selectedMain || !selectedSub) return;

            const locationName = `${selectedMain.name} - ${selectedSub.name}`;
            const characters = selectedCharacters.join(',');

            // 构建移动消息
            let message = `<request:{{user}}前往了${locationName}.`;
            if (characters) {
                message += `${characters}在那里`;
            }
            message += ">";

            // 获取发送模式（直接发送或放入输入框）
            const directSendMode = document.getElementById('direct-send-toggle').checked;

            // 根据发送模式执行不同操作
            if (directSendMode) {
                // 直接发送模式 - 如果存在 triggerSlash 函数，发送消息
                if (typeof triggerSlash === 'function') {
                    try {
                        triggerSlash(`/send ${message} || /trigger`);
                    } catch (e) {
                        console.error("发送消息时出错:", e);
                        alert("发送消息失败，请重试。");
                    }
                } else {
                    console.log("移动命令:", message);
                    alert("移动请求已生成。在实际环境中，这将发送到AI。");
                }
            } else {
                // 仅放入输入框模式
                if (typeof triggerSlash === 'function') {
                    try {
                        triggerSlash(`/setinput ${message}`);
                    } catch (e) {
                        console.error("设置输入框时出错:", e);
                        alert("设置输入框失败，请重试。");
                    }
                } else {
                    console.log("输入框内容已设置:", message);
                    alert("消息已放入输入框，请手动编辑和发送。");
                }
            }

            // 隐藏确认对话框
            document.getElementById('confirm-overlay').classList.add('hidden');

            // 重置选择
            resetSelection();
        }

        // 重置选择
        function resetSelection() {
            selectedMain = null;
            selectedSub = null;
            selectedCharacters = [];

            // 清除所有选中状态
            document.querySelectorAll('.location-button, .sub-location-button').forEach(btn => {
                btn.classList.remove('selected');
            });

            // 隐藏子地点和详情
            document.getElementById('sub-locations').classList.add('hidden');
            document.getElementById('location-details').classList.add('hidden');
        }

        // 处理地图数据
        function processMapData() {
            const dataSource = document.getElementById('map-data-source');
            if (!dataSource) {
                console.error("未找到地图数据源元素");
                return;
            }

            let mapText = null;
            let dataSource_used = false;
            console.log("开始查找地图数据...");

            // 首先尝试从文档中获取<map_data>标签内容（最优先）
            function findMapDataTag(text) {
                if (!text) return null;

                // 1. 排除<details>标签内容中不完整的<map_data>标签
                // 首先检查是否存在<details>标签
                if (text.includes('<details>') && text.includes('<map_data>')) {
                    // 更精确的<map_data>标签匹配，确保它是完整的标签对
                    const mapDataRegex = /<map_data>([\s\S]*?)\[MOVEBLOCK:(YES|NO)\]([\s\S]*?)<\/map_data>/;
                    const match = mapDataRegex.exec(text);

                    if (match && match[2] && match[3] && match[3].includes('-')) {
                        console.log("找到包含完整MOVEBLOCK和子地点的<map_data>标签");
                        const fullContent = (match[1] || '') + '[MOVEBLOCK:' + match[2] + ']' + match[3];
                        return fullContent.trim();
                    }
                } else {
                    // 如果不存在<details>标签冲突，使用简单匹配
                    const mapDataRegex = /<map_data>([\s\S]*?)<\/map_data>/;
                    const match = mapDataRegex.exec(text);
                    if (match && match[1] && match[1].trim()) {
                        // 额外验证：确保内容包含地图数据的特征
                        const content = match[1].trim();
                        if (content.includes('[MOVEBLOCK:') && content.includes(']') && content.includes('-')) {
                            return content;
                        }
                    }
                }
                return null;
            }

            // 尝试从父窗口获取数据（SillyTavern环境）
            try {
                if (window.parent && window.parent !== window) {
                    console.log("在iframe中运行，尝试仅从当前消息获取地图数据");

                    // 1. 首先从URL参数中查找（最高优先级）
                    try {
                        const urlParams = new URLSearchParams(window.location.search);
                        const urlData = urlParams.get('data');
                        if (urlData) {
                            const decodedData = decodeURIComponent(urlData);
                            console.log("检查URL参数中的数据...");

                            // 检查URL参数中是否包含<map_data>标签
                            const tagData = findMapDataTag(decodedData);
                            if (tagData) {
                                console.log("在URL参数中找到<map_data>标签数据");
                                mapText = tagData;
                            }
                        }
                    } catch (e) {
                        console.log("URL参数处理出错:", e);
                    }

                    // 2. 尝试获取当前iframe所在的消息元素
                    if (!mapText) {
                        try {
                            // 获取当前iframe元素
                            const currentIframe = window.frameElement;
                            if (currentIframe) {
                                // 查找当前iframe的父级消息元素
                                let parentMessage = currentIframe;

                                // 向上查找直到找到消息元素
                                while (parentMessage && 
                                      !parentMessage.classList.contains('mes_text') && 
                                      !parentMessage.classList.contains('mes_content') && 
                                      !parentMessage.classList.contains('message-content') && 
                                      !parentMessage.classList.contains('message_text')) {
                                    parentMessage = parentMessage.parentElement;
                                }

                                if (parentMessage) {
                                    console.log("找到当前iframe所在的消息元素");
                                    const messageText = parentMessage.textContent || parentMessage.innerText;

                                    // 先尝试查找<map_data>标签
                                    const tagData = findMapDataTag(messageText);
                                    if (tagData) {
                                        console.log("在当前消息中找到<map_data>标签数据");
                                        mapText = tagData;
                                    } else {
                                        // 尝试提取符合格式的地图数据
                                        const extractedData = extractMapData(messageText);
                                        if (extractedData) {
                                            console.log("在当前消息中提取到符合格式的地图数据");
                                            mapText = extractedData;
                                        }
                                    }
                                } else {
                                    console.log("未找到当前iframe所在的消息元素");
                                }
                            }
                        } catch (e) {
                            console.log("获取当前消息元素出错:", e);
                        }
                    }

                    // 严格的地图数据匹配，必须包含[MOVEBLOCK:开头和多个地点块
                    function extractMapData(text) {
                        if (!text) return null;

                        // 更严格的地图数据匹配模式
                        // 1. 必须以[MOVEBLOCK:YES|NO]开头
                        // 2. 必须包含至少一个主地点块，以"["开头，以"]"结尾
                        // 3. 主地点块内必须有至少一个子地点行，格式为"- 子地点名: [角色列表]"
                        const fullMapRegex = /\[MOVEBLOCK:(YES|NO)\][\s\n]*((?:\[[\s\S]*?(?:-\s+[^:]+:[^\]]*)*\][\s\n]*)+)/;
                        const match = fullMapRegex.exec(text);

                        if (match && match[2] && match[2].trim()) {
                            const mapContent = "[MOVEBLOCK:" + match[1] + "]\n" + match[2].trim();

                            // 额外验证：确保数据包含主地点和子地点格式
                            if (mapContent.match(/\[.+\n\s*-\s+.+:/)) {
                                console.log("找到符合严格地图格式的数据块");
                                return mapContent;
                            }
                        }
                        return null;
                    }
                }
            } catch (e) {
                console.log("数据获取过程出错:", e);
            }

            // 如果在其他地方找不到地图数据，使用dataSource中的数据
            if (!mapText) {
                const sourceText = dataSource.textContent || dataSource.innerText;
                if (sourceText && sourceText.trim()) {
                    console.log("使用data-source中的地图数据");
                    mapText = sourceText;
                    dataSource_used = true;
                }
            }

            // 如果仍然没有找到有效数据，使用测试数据
            if (!mapText || (!mapText.includes('[MOVEBLOCK:') && !mapText.includes('- ') && !mapText.includes(']'))) {
                console.log("未找到有效地图数据，使用测试数据");
                mapText = `[MOVEBLOCK:NO]
[校园区域
- 教学楼: 班主任, 数学老师
- 图书馆: 文学社社长, 图书管理员
- 操场: 体育老师, 田径队队长]
[商业街
- 咖啡厅: 服务员小雅, 钢琴少女
- 游戏厅: 游戏高手小明, 不良少年
- 书店: 眼镜店主, 神秘顾客]
[住宅区
- 公寓楼: 邻居阿姨, 宠物猫咪
- 小公园: 晨练老人, 遛狗少年
- 便利店: 店长, 兼职学生]`;

                if (!dataSource_used) {
                    dataSource.textContent = mapText;
                    console.log("已设置测试数据");
                }
            }

            // 兼容旧版数据格式（EMOTION -> MOVEBLOCK）
            if (mapText && mapText.includes('[EMOTION:')) {
                console.log("转换旧版数据格式（EMOTION -> MOVEBLOCK）");
                mapText = mapText.replace(/\[EMOTION:(BAD|GOOD)\]/g, function(match, state) {
                    return `[MOVEBLOCK:${state === 'BAD' ? 'YES' : 'NO'}]`;
                });
            }

            // 检查提取的数据质量
            let isValidMapData = false;
            if (mapText) {
                try {
                    // 检查数据是否包含必要的地图元素，使用更严格的验证
                    const hasMoveBlock = mapText.includes('[MOVEBLOCK:');
                    const hasProperLocation = !!mapText.match(/\[(?!MOVEBLOCK)[^\[\]<>]+\n\s*-\s+[^:]+:/);

                    isValidMapData = hasMoveBlock && hasProperLocation;
                    console.log("地图数据质量检查:", isValidMapData ? "有效" : "无效", 
                        "| 包含MOVEBLOCK:", hasMoveBlock, 
                        "| 包含正确格式的地点块:", hasProperLocation);

                    if (isValidMapData) {
                        // 打印找到的地图数据的完整结构（为了调试）
                        console.log("地图数据结构验证:");
                        const moveblockMatch = /\[MOVEBLOCK:(YES|NO)\]/.exec(mapText);
                        if (moveblockMatch) {
                            console.log("- MOVEBLOCK状态:", moveblockMatch[1]);
                        }

                        // 计算主地点和子地点数量
                        const mainLocCount = (mapText.match(/\[(?!MOVEBLOCK:)[^\[\]<>]+\n/g) || []).length;
                        const subLocCount = (mapText.match(/\n\s*-\s+[^:]+:/g) || []).length;
                        console.log(`- 包含 ${mainLocCount} 个主地点, ${subLocCount} 个子地点`);

                        if (mainLocCount === 0 || subLocCount === 0) {
                            console.warn("地图数据格式异常：缺少主地点或子地点");
                            isValidMapData = false;
                        }
                    }

                    if (!isValidMapData) {
                        console.warn("提取的地图数据不完整或格式不正确");
                        console.log("问题数据样本:", mapText.substring(0, Math.min(200, mapText.length)));
                    }
                } catch (e) {
                    console.error("验证地图数据时出错:", e);
                    isValidMapData = false;
                }
            }

            // 调试输出处理后的地图数据
            console.log("准备解析的地图数据:", mapText ? (mapText.substring(0, Math.min(100, mapText.length)) + "...") : "无数据");

            // 现在解析和渲染地图数据
            try {
                mapData = parseMapData(mapText);

                if (mapData && mapData.locations && mapData.locations.length > 0) {
                    console.log(`成功解析地图数据: ${mapData.locations.length} 个主地点`);
                    renderMapInterface(mapData);
                } else {
                    console.error("地图数据解析失败或没有地点数据");
                    if (mapText) {
                        console.log("原始数据:", mapText.substring(0, Math.min(300, mapText.length)));
                    }
                }
            } catch (e) {
                console.error("解析或渲染地图数据时出错:", e);
            }
        }

        // 注册事件监听器
        function setupEventListeners() {
            // 确认移动按钮
            document.getElementById('confirm-move-btn').addEventListener('click', confirmMove);

            // 确认对话框按钮
            document.getElementById('cancel-move-btn').addEventListener('click', () => {
                document.getElementById('confirm-overlay').classList.add('hidden');
            });

            document.getElementById('execute-move-btn').addEventListener('click', executeMove);

            // 发送模式切换按钮
            const toggleSwitch = document.getElementById('direct-send-toggle');
            if (toggleSwitch) {
                toggleSwitch.addEventListener('change', function() {
                    const label = this.parentElement.nextElementSibling;
                    if (this.checked) {
                        label.textContent = "直接发送";
                        label.style.color = "var(--gal-success)";
                    } else {
                        label.textContent = "放入输入框";
                        label.style.color = "var(--gal-primary)";
                    }
                });

                // 初始状态设置
                const label = toggleSwitch.parentElement.nextElementSibling;
                if (toggleSwitch.checked) {
                    label.textContent = "直接发送";
                    label.style.color = "var(--gal-success)";
                } else {
                    label.textContent = "放入输入框";
                    label.style.color = "var(--gal-primary)";
                }
            }
        }

        // 初始化
        function init() {
            // 设置事件监听器
            setupEventListeners();

            // 处理地图数据
            processMapData();

            // 监听SillyTavern消息更新
            if (window.parent && window.parent !== window && typeof window.parent.eventOn === 'function' && window.parent.tavern_events) {
                // 获取当前iframe所在的消息元素ID
                let currentMessageId = null;
                try {
                    const currentIframe = window.frameElement;
                    if (currentIframe) {
                        // 查找当前iframe的父级消息元素
                        let parentMessage = currentIframe;
                        while (parentMessage && 
                              !parentMessage.classList.contains('mes_block') && 
                              !parentMessage.classList.contains('mes_wrap') && 
                              !parentMessage.classList.contains('message-wrap')) {
                            parentMessage = parentMessage.parentElement;
                        }

                        if (parentMessage && parentMessage.id) {
                            currentMessageId = parentMessage.id;
                            console.log("当前iframe所在消息ID:", currentMessageId);
                        }
                    }
                } catch (e) {
                    console.log("获取当前消息ID出错:", e);
                }

                // 只在当前消息更新时刷新地图数据
                window.parent.eventOn(window.parent.tavern_events.MESSAGE_UPDATED, (messageId) => {
                    if (currentMessageId && messageId === currentMessageId) {
                        console.log("当前消息已更新，刷新地图数据");
                        setTimeout(processMapData, 300);
                    }
                });

                // 如果无法确定具体消息ID，则默认使用全局更新监听
                if (!currentMessageId) {
                    window.parent.eventOn(window.parent.tavern_events.MESSAGE_UPDATED, () => {
                        setTimeout(processMapData, 300);
                    });
                    window.parent.eventOn(window.parent.tavern_events.MESSAGE_RECEIVED, () => {
                        setTimeout(processMapData, 300);
                    });
                }
            }
        }

        // 页面加载完成后初始化
        document.addEventListener('DOMContentLoaded', init);
    </script>

